using System;
using System.IO;
using System.Windows.Media;
using System.Windows.Media.Imaging;

namespace FamilyConverter.Revit2021.UI
{
    internal static class EmbeddedIcons
    {
        private const string SettingsIconBase64 =
"";

        private const string AiIconBase64 =
"";

        public static ImageSource CreateSettings()
        {
            return Load(SettingsIconBase64);
        }

        public static ImageSource CreateAi()
        {
            return Load(AiIconBase64);
        }

        private static ImageSource Load(string base64)
        {
            byte[] bytes = Convert.FromBase64String(base64);
            using (var stream = new MemoryStream(bytes))
            {
                var image = new BitmapImage();
                image.BeginInit();
                image.StreamSource = stream;
                image.CacheOption = BitmapCacheOption.OnLoad;
                image.EndInit();
                image.Freeze();
                return image;
            }
        }
    }
}
